def describe_coordination_intelligence() -> str:
    lines = [
        "TitanAI Advanced Autonomous Intelligence Network Era",
        "",
        "This layer frames TitanAI as a complete intelligence coordination system for software companies, product studios, startups, knowledge work, infrastructure, simulation, reliability, creation, assistants, governance, collaboration, and operating-system-style control.",
        "",
    ]
    for capability in COORDINATION_CAPABILITIES:
        lines.append(f"- {capability.version} {capability.name} [{capability.category}]")
        lines.append(f"  {capability.purpose}")
    return "\n".join(lines)
